package weibo

import (
	"os"
	"testing"

	"github.com/Brilliant666/DokiTool-Go/backend/internal/unified"
)

// Public expected values are generated by the original frozen PHP 8.3.6
// snapAdaptWeibo / snapFinalizeData / snapPublicMediaView functions, never
// from the Go adapter. This is the unsigned, unfiltered private-to-public
// boundary. Signed relay projection is tested independently.
func TestFrozenPHPWeiboPublicAdapter(t *testing.T) {
	data, err := os.ReadFile("testdata/php-public-baseline.json")
	if err != nil {
		t.Fatal(err)
	}
	fixture, err := unified.Decode(data)
	if err != nil {
		t.Fatal(err)
	}
	if fixture["php_source_commit"] != "25beaee107f8c1a208ced9deb3c637068445e316" {
		t.Fatal("unexpected PHP provenance")
	}
	cases := unified.Slice(fixture["cases"])
	if len(cases) != 29 {
		t.Fatalf("incomplete PHP public adapter baseline: %d", len(cases))
	}
	for _, raw := range cases {
		entry := unified.Map(raw)
		t.Run(unified.Str(entry["id"]), func(t *testing.T) {
			input := unified.Map(entry["input"])
			expected := unified.Map(entry["expected"])
			observedNow, ok := unified.Numeric(input["now"])
			if !ok {
				t.Fatal("missing independent clock")
			}
			now := int64(observedNow)
			internal := adaptLegacy(unified.Map(input["legacy"]), unified.Str(input["source"]), now)
			views := map[string]unified.Object{
				"internal": internal,
				"normal":   unified.PublicView(internal, false, now),
				"debug":    unified.PublicView(internal, true, now),
			}
			for view, actual := range views {
				if !unified.Equal(actual, expected[view]) {
					got, _ := unified.Encode(actual)
					want, _ := unified.Encode(expected[view])
					t.Fatalf("original PHP %s differs:\nGo: %s\nPHP: %s", view, got, want)
				}
				if err := unified.ValidateEnvelopeAt(actual, now); err != nil {
					t.Fatalf("invalid %s view: %v", view, err)
				}
			}
		})
	}
}
